using System;using System.Linq;using System.Collections.Generic;
namespace IanGame {
public static class GachaProbabilityDisclosure {
 public static string Describe(ItemService items,string poolId){var p=items.catalog.Pool(poolId);if(p==null)return "Pool 없음";string List(Dictionary<string,double> odds)=>string.Join("\n",odds.Select(e=>items.catalog.Item(e.Key).displayName+" · "+items.catalog.Rarity(items.catalog.Item(e.Key).rarityId).displayName+" · "+(e.Value*100).ToString("0.######")+"%"));return p.displayName+"\n현재 연령의 실제 추첨 데이터 · 개별 확률\n\n"+List(items.Gacha.Probabilities(poolId))+"\n\n다음 1회 (현재 천장 반영)\n"+List(items.Gacha.Probabilities(poolId,true))+"\n\n천장 규칙\n"+string.Join("\n",p.pityRules.Select(r=>r.threshold+"회: "+(!string.IsNullOrEmpty(r.guaranteedItem)?items.catalog.Item(r.guaranteedItem).displayName:items.catalog.Rarity(r.minimumRarityId).displayName+" 이상")+" / 초기화: "+r.reset))+"\n\n동일 아이템 중복 획득이 가능합니다. 겹치는 천장은 결과 1개에 함께 적용되며 가장 높은 우선순위의 특정 아이템 보장이 우선합니다.\n10회는 각 회차의 천장 상태를 순서대로 반영합니다. 표시 반올림으로 합계에 미세한 차이가 날 수 있습니다. 확률 변경은 업데이트 고지 후 해당 데이터가 적용된 추첨부터 효력이 있습니다.";}
 public static string Validate(ItemCatalog catalog){var error=catalog?.Validate();if(catalog==null||error!=null)return error??"Catalog missing";foreach(var pool in catalog.pools)foreach(int age in new[]{pool.minAge,19,30,60}.Where(a=>a>=pool.minAge))foreach(var rules in new[]{Array.Empty<PityRule>(),pool.pityRules}.Concat(pool.pityRules.Select(r=>new[]{r}))){var odds=GachaService.Compute(catalog,age,pool,rules);if(odds.Count==0||odds.Any(o=>double.IsNaN(o.Value)||double.IsInfinity(o.Value)||o.Value<0)||Math.Abs(odds.Values.Sum()-1)>1e-10)return "Probability sum invalid: "+pool.poolId+" age "+age;}return null;}
}
}
